"use client";

import { useMemo, useRef, useState, type FormEvent, type ReactNode } from "react";
import { useSearchParams } from "next/navigation";
import {
  Activity,
  Building2,
  ChevronLeft,
  ChevronRight,
  Download,
  EllipsisVertical,
  ExternalLink,
  FileText,
  Linkedin,
  Mail,
  MessageSquareText,
  Phone,
  Search,
  Settings2,
  Star,
  TrendingUp,
  UserRound,
  UsersRound,
  X,
} from "lucide-react";
import { toast } from "sonner";
import { Avatar, AvatarFallback } from "@/shared/components/ui/avatar";
import { cn, formatDate, getInitials } from "@/shared/lib/utils";
import { mockCompanies, mockContacts } from "../constants/mock-relationships";
import type { CompanyDraft, CompanyRecord, ContactDraft, ContactRecord, ContactStatus, RelationshipView } from "../types";

const owners = ["Alex Morgan", "Priya Shah"];
const statuses: ContactStatus[] = ["customer", "prospect", "partner"];
const statusStyle: Record<ContactStatus, string> = {
  customer: "border-emerald-500/25 bg-emerald-500/10 text-emerald-400",
  prospect: "border-sky-500/25 bg-sky-500/10 text-sky-400",
  partner: "border-violet-500/25 bg-violet-500/10 text-violet-300",
};
type Selection = { kind: RelationshipView; id: string } | null;

function money(value: number) {
  return new Intl.NumberFormat("en-US", { style: "currency", currency: "USD", maximumFractionDigits: 0, notation: "compact" }).format(value);
}

function MetricCard({ label, value, delta, icon: Icon, gold = false }: { label: string; value: string; delta: string; icon: typeof UserRound; gold?: boolean }) {
  return <article className="orion-panel p-4"><div className="flex items-start justify-between"><div><p className="text-[10px] text-muted-foreground">{label}</p><p className="mt-1.5 text-xl font-semibold text-foreground">{value}</p></div><span className={cn("grid h-8 w-8 place-items-center rounded-full border", gold ? "border-amber-400/20 bg-amber-400/10 text-amber-400" : "border-primary/20 bg-primary/10 text-primary")}><Icon className="h-4 w-4" /></span></div><p className="mt-2 text-[9px] text-success">↑ {delta} <span className="text-muted-foreground">vs last month</span></p></article>;
}

function StatusBadge({ status }: { status: ContactStatus }) {
  return <span className={cn("rounded-full border px-2 py-0.5 text-[9px] capitalize", statusStyle[status])}>{status}</span>;
}

function RecordDialog({ kind, companies, contact, company, onClose, onSave }: { kind: RelationshipView; companies: CompanyRecord[]; contact?: ContactRecord; company?: CompanyRecord; onClose: () => void; onSave: (draft: ContactDraft | CompanyDraft) => void }) {
  const [contactDraft, setContactDraft] = useState<ContactDraft>({ name: contact?.name ?? "", title: contact?.title ?? "", email: contact?.email ?? "", phone: contact?.phone ?? "", companyId: contact?.companyId ?? companies[0]?.id ?? "", owner: contact?.owner ?? owners[0], status: contact?.status ?? "prospect" });
  const [companyDraft, setCompanyDraft] = useState<CompanyDraft>({ name: company?.name ?? "", industry: company?.industry ?? "", size: company?.size ?? "51–200", website: company?.website ?? "", phone: company?.phone ?? "", headquarters: company?.headquarters ?? "", owner: company?.owner ?? owners[0], status: company?.status ?? "prospect" });

  function submit(event: FormEvent) {
    event.preventDefault();
    const draft = kind === "contacts" ? contactDraft : companyDraft;
    if (!draft.name.trim()) return toast.error(`${kind === "contacts" ? "Contact" : "Company"} name is required`);
    if (kind === "contacts" && !(draft as ContactDraft).email.includes("@")) return toast.error("Enter a valid email address");
    onSave(draft);
  }

  return <div className="fixed inset-0 z-50 grid place-items-center p-4" role="dialog" aria-modal="true" aria-labelledby="record-dialog-title"><button type="button" aria-label="Close record dialog" className="absolute inset-0 bg-black/70 backdrop-blur-sm" onClick={onClose} /><form onSubmit={submit} className="neon-panel relative z-10 w-full max-w-2xl rounded-2xl p-5 shadow-floating"><header className="flex items-start justify-between"><div><h2 id="record-dialog-title" className="text-base font-semibold text-foreground">{contact || company ? "Edit" : "Add"} {kind === "contacts" ? "contact" : "company"}</h2><p className="mt-1 text-xs text-muted-foreground">Keep relationship data accurate and actionable for the whole team.</p></div><button type="button" aria-label="Close" onClick={onClose} className="grid h-8 w-8 place-items-center rounded-lg text-muted-foreground hover:bg-foreground/[0.06]"><X className="h-4 w-4" /></button></header>
    {kind === "contacts" ? <div className="mt-5 grid gap-4 sm:grid-cols-2"><Field label="Full name"><input autoFocus value={contactDraft.name} onChange={(e) => setContactDraft((d) => ({ ...d, name: e.target.value }))} className="field" /></Field><Field label="Job title"><input value={contactDraft.title} onChange={(e) => setContactDraft((d) => ({ ...d, title: e.target.value }))} className="field" /></Field><Field label="Email"><input type="email" value={contactDraft.email} onChange={(e) => setContactDraft((d) => ({ ...d, email: e.target.value }))} className="field" /></Field><Field label="Phone"><input value={contactDraft.phone} onChange={(e) => setContactDraft((d) => ({ ...d, phone: e.target.value }))} className="field" /></Field><Field label="Company"><select value={contactDraft.companyId} onChange={(e) => setContactDraft((d) => ({ ...d, companyId: e.target.value }))} className="field">{companies.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></Field><Field label="Owner"><select value={contactDraft.owner} onChange={(e) => setContactDraft((d) => ({ ...d, owner: e.target.value }))} className="field">{owners.map((owner) => <option key={owner}>{owner}</option>)}</select></Field><Field label="Relationship"><select value={contactDraft.status} onChange={(e) => setContactDraft((d) => ({ ...d, status: e.target.value as ContactStatus }))} className="field">{statuses.map((status) => <option key={status} value={status}>{status}</option>)}</select></Field></div> : <div className="mt-5 grid gap-4 sm:grid-cols-2"><Field label="Company name"><input autoFocus value={companyDraft.name} onChange={(e) => setCompanyDraft((d) => ({ ...d, name: e.target.value }))} className="field" /></Field><Field label="Industry"><input value={companyDraft.industry} onChange={(e) => setCompanyDraft((d) => ({ ...d, industry: e.target.value }))} className="field" /></Field><Field label="Company size"><select value={companyDraft.size} onChange={(e) => setCompanyDraft((d) => ({ ...d, size: e.target.value }))} className="field">{["1–50", "51–200", "201–500", "501–1,000", "1,001–5,000", "5,000+"].map((size) => <option key={size}>{size}</option>)}</select></Field><Field label="Website"><input value={companyDraft.website} onChange={(e) => setCompanyDraft((d) => ({ ...d, website: e.target.value }))} className="field" /></Field><Field label="Phone"><input value={companyDraft.phone} onChange={(e) => setCompanyDraft((d) => ({ ...d, phone: e.target.value }))} className="field" /></Field><Field label="Headquarters"><input value={companyDraft.headquarters} onChange={(e) => setCompanyDraft((d) => ({ ...d, headquarters: e.target.value }))} className="field" /></Field><Field label="Owner"><select value={companyDraft.owner} onChange={(e) => setCompanyDraft((d) => ({ ...d, owner: e.target.value }))} className="field">{owners.map((owner) => <option key={owner}>{owner}</option>)}</select></Field><Field label="Relationship"><select value={companyDraft.status} onChange={(e) => setCompanyDraft((d) => ({ ...d, status: e.target.value as ContactStatus }))} className="field">{statuses.map((status) => <option key={status} value={status}>{status}</option>)}</select></Field></div>}
    <footer className="mt-6 flex justify-end gap-2"><button type="button" onClick={onClose} className="rounded-lg border border-border px-4 py-2 text-xs text-muted-foreground">Cancel</button><button type="submit" className="orion-add-widget rounded-lg px-4 py-2 text-xs font-semibold">{contact || company ? "Save changes" : `Add ${kind === "contacts" ? "contact" : "company"}`}</button></footer></form></div>;
}

function Field({ label, children }: { label: string; children: ReactNode }) {
  return <label className="text-[11px] font-medium text-muted-foreground">{label}<span className="mt-1.5 block [&_.field]:h-10 [&_.field]:w-full [&_.field]:rounded-lg [&_.field]:border [&_.field]:border-border [&_.field]:bg-black/10 [&_.field]:px-3 [&_.field]:text-sm [&_.field]:text-foreground [&_.field]:outline-none">{children}</span></label>;
}

function ContactProfilePanel({ contact, company, onClose, onEdit, onDelete, onCompany, onAddNote, onStatusChange }: { contact: ContactRecord; company?: CompanyRecord; onClose: () => void; onEdit: () => void; onDelete: () => void; onCompany: () => void; onAddNote: (note: string) => void; onStatusChange: (status: ContactStatus) => void }) {
  const [noteOpen, setNoteOpen] = useState(false);
  const [note, setNote] = useState("");
  const [menuOpen, setMenuOpen] = useState(false);
  const score = company ? Math.min(99, Math.round((company.score + (contact.status === "customer" ? 10 : 0)) / 1.05)) : 72;

  function submitNote(event: FormEvent) {
    event.preventDefault();
    if (!note.trim()) return;
    onAddNote(note.trim());
    setNote("");
    setNoteOpen(false);
  }

  return <div className="fixed inset-0 z-40 bg-black/45 backdrop-blur-[2px]" role="presentation" onMouseDown={(event) => { if (event.target === event.currentTarget) onClose(); }}><aside aria-label={`${contact.name} details`} className="neon-panel absolute bottom-3 right-3 top-3 flex w-[320px] max-w-[calc(100vw-24px)] flex-col overflow-hidden rounded-2xl shadow-floating">
    <header className="flex h-12 items-center justify-between border-b border-border px-4"><h2 className="text-xs font-semibold text-foreground">Contact Details</h2><div className="flex items-center gap-1"><button type="button" aria-label="Open full profile" onClick={() => toast.info("Full profile view is ready")} className="grid h-7 w-7 place-items-center rounded-md text-muted-foreground hover:bg-foreground/[0.06] hover:text-primary"><ExternalLink className="h-3.5 w-3.5" /></button><button type="button" aria-label="Close" onClick={onClose} className="grid h-7 w-7 place-items-center rounded-md text-muted-foreground hover:bg-foreground/[0.06] hover:text-foreground"><X className="h-4 w-4" /></button></div></header>
    <div className="min-h-0 flex-1 overflow-y-auto px-4 pb-5"><section className="flex items-start gap-3 py-4"><Avatar className="h-12 w-12 border-2 border-foreground/70 shadow-lg"><AvatarFallback className="bg-gradient-to-br from-primary/30 to-sky-500/20 text-sm font-semibold text-foreground">{getInitials(contact.name)}</AvatarFallback></Avatar><div className="min-w-0 pt-0.5"><h3 className="truncate text-sm font-semibold text-foreground">{contact.name}</h3><p className="mt-0.5 text-[9px] text-muted-foreground">{contact.title}</p><button type="button" onClick={onCompany} disabled={!company} className="mt-2 flex items-center gap-1.5 text-[9px] text-foreground hover:text-primary disabled:cursor-default"><Building2 className="h-3 w-3 text-muted-foreground" />{company?.name ?? "No company assigned"}</button></div></section>
    <div className="relative flex gap-2 border-b border-border pb-4">{[[Mail, "Email"], [Phone, "Call"], [Linkedin, "LinkedIn"]].map(([Icon, label]) => <button key={label as string} type="button" aria-label={label as string} onClick={() => toast.success(`${label as string} action started for ${contact.name}`)} className="orion-glass-control grid h-9 w-11 place-items-center rounded-lg text-muted-foreground transition hover:border-primary/30 hover:text-primary"><Icon className="h-3.5 w-3.5" /></button>)}<button type="button" aria-label="More" aria-expanded={menuOpen} onClick={() => setMenuOpen((open) => !open)} className="orion-glass-control grid h-9 w-11 place-items-center rounded-lg text-muted-foreground hover:border-primary/30 hover:text-primary"><EllipsisVertical className="h-3.5 w-3.5" /></button>{menuOpen ? <div className="absolute left-[150px] top-11 z-20 w-32 rounded-lg border border-border bg-popover/95 p-1 shadow-floating backdrop-blur-xl"><button type="button" onClick={onEdit} className="block w-full rounded-md px-2.5 py-2 text-left text-[9px] text-foreground hover:bg-foreground/[0.06]">Edit contact</button><button type="button" onClick={onDelete} className="block w-full rounded-md px-2.5 py-2 text-left text-[9px] text-destructive hover:bg-destructive/10">Delete contact</button></div> : null}</div>
    <section className="space-y-3 border-b border-border py-4 text-[9px]"><div className="grid grid-cols-[78px_1fr] items-center gap-2"><span className="text-muted-foreground">Status</span><select aria-label="Contact status" value={contact.status} onChange={(event) => onStatusChange(event.target.value as ContactStatus)} className="orion-add-widget h-8 w-[124px] justify-self-end rounded-lg px-2 text-[9px] capitalize outline-none">{statuses.map((item) => <option key={item} value={item}>{item}</option>)}</select></div>
    <dl className="space-y-3">{[["Email", contact.email], ["Phone", contact.phone], ["Company Size", company?.size ?? "—"], ["Industry", company?.industry ?? "—"], ["Lead Source", "Website"]].map(([label, value]) => <div key={label} className="grid grid-cols-[78px_1fr] gap-2"><dt className="text-muted-foreground">{label}</dt><dd className="break-words text-foreground">{value}</dd></div>)}<div className="grid grid-cols-[78px_1fr] items-center gap-2"><dt className="text-muted-foreground">Owner</dt><dd className="flex items-center gap-2 text-foreground"><Avatar className="h-5 w-5"><AvatarFallback className="text-[7px]">{getInitials(contact.owner)}</AvatarFallback></Avatar>{contact.owner}</dd></div><div className="grid grid-cols-[78px_1fr] items-center gap-2"><dt className="text-muted-foreground">Score</dt><dd className="flex items-center gap-2 text-foreground"><span className="h-2 w-2 rounded-full bg-success shadow-[0_0_8px_rgba(34,197,94,.5)]" />{score}</dd></div><div className="grid grid-cols-[78px_1fr] items-start gap-2"><dt className="pt-1 text-muted-foreground">Tags</dt><dd className="flex flex-wrap gap-1.5">{contact.tags.map((tag, index) => <span key={tag} className={cn("rounded-full border px-2 py-1 text-[8px]", index ? "border-orange-400/20 bg-orange-400/10 text-orange-300" : "border-emerald-400/20 bg-emerald-400/10 text-emerald-300")}>{tag}</span>)}<button type="button" aria-label="Add tag" onClick={() => toast.info("Tag manager opened")} className="grid h-5 w-5 place-items-center rounded-full border border-border text-muted-foreground">+</button></dd></div></dl></section>
    <section className="border-b border-border py-4"><div className="flex items-center justify-between"><h3 className="text-xs font-medium text-foreground">Notes</h3><button type="button" onClick={() => setNoteOpen((open) => !open)} className="text-[9px] text-primary">{noteOpen ? "Cancel" : "Add Note"}</button></div>{noteOpen ? <form onSubmit={submitNote} className="orion-glass-control mt-3 rounded-xl p-3"><textarea autoFocus value={note} onChange={(event) => setNote(event.target.value)} placeholder="Add relationship context…" className="min-h-16 w-full resize-none bg-transparent text-[10px] text-foreground outline-none" /><div className="text-right"><button type="submit" className="rounded-md bg-primary/15 px-2.5 py-1 text-[9px] text-primary">Save note</button></div></form> : null}<div className="mt-3 space-y-2">{contact.notes.slice(0, 2).map((item, index) => <article key={`${item}-${index}`} className="orion-glass-control rounded-xl p-3"><p className="text-[10px] leading-4 text-foreground">{item}</p><p className="mt-2 text-[8px] text-muted-foreground">{contact.owner} · {index ? "Yesterday" : "Today, 10:30 AM"}</p></article>)}</div></section>
    <section className="py-4"><div className="flex items-center justify-between"><h3 className="text-xs font-medium text-foreground">Attachments</h3><button type="button" onClick={() => toast.info("Showing all contact files")} className="text-[9px] text-primary">View all</button></div><div className="orion-glass-control mt-3 flex items-center gap-3 rounded-xl p-3"><span className="grid h-8 w-8 place-items-center rounded-lg bg-emerald-500/15 text-emerald-400"><FileText className="h-4 w-4" /></span><span className="min-w-0 flex-1"><span className="block truncate text-[10px] text-foreground">{contact.name.toLowerCase().replaceAll(" ", "_")}_requirements.pdf</span><span className="text-[8px] text-muted-foreground">PDF · 2.4 MB</span></span><button type="button" aria-label="Download attachment" onClick={() => toast.success("Attachment download started")} className="grid h-7 w-7 place-items-center text-muted-foreground hover:text-primary"><Download className="h-3.5 w-3.5" /></button></div></section></div>
  </aside></div>;
}

type CompanyTab = "overview" | "contacts" | "deals" | "activity" | "files";

function CompanyProfilePanel({ company, contacts, followed, onFollow, onClose, onEdit, onDelete, onContact, onAddNote }: { company: CompanyRecord; contacts: ContactRecord[]; followed: boolean; onFollow: () => void; onClose: () => void; onEdit: () => void; onDelete: () => void; onContact: (id: string) => void; onAddNote: (note: string) => void }) {
  const [tab, setTab] = useState<CompanyTab>("overview");
  const [noteOpen, setNoteOpen] = useState(false);
  const [note, setNote] = useState("");
  const [menuOpen, setMenuOpen] = useState(false);

  function submitNote(event: FormEvent) {
    event.preventDefault();
    if (!note.trim()) return;
    onAddNote(note.trim());
    setNote("");
    setNoteOpen(false);
  }

  const activity = [
    ["Contract.pdf uploaded", "May 20, 2024"],
    ["Follow-up email sent", "May 19, 2024"],
    ["Deal stage updated to Proposal", "May 11, 2024"],
  ];
  const tabs: { id: CompanyTab; label: string }[] = [
    { id: "overview", label: "Overview" },
    { id: "contacts", label: `Contacts (${Math.max(contacts.length, 24)})` },
    { id: "deals", label: `Deals (${company.deals})` },
    { id: "activity", label: "Activity" },
    { id: "files", label: "Files" },
  ];

  return <div className="fixed inset-0 z-40 bg-black/45 backdrop-blur-[2px]" role="presentation" onMouseDown={(event) => { if (event.target === event.currentTarget) onClose(); }}><aside aria-label={`${company.name} details`} className="neon-panel absolute bottom-3 right-3 top-3 flex w-[460px] max-w-[calc(100vw-24px)] flex-col overflow-hidden rounded-2xl shadow-floating">
    <header className="px-5 pt-5"><div className="flex items-start gap-3"><Avatar className="h-12 w-12 rounded-lg border border-primary/20"><AvatarFallback className="rounded-lg bg-gradient-to-br from-slate-500/50 to-primary/10 text-sm font-semibold text-foreground">{company.name[0]}</AvatarFallback></Avatar><div className="min-w-0 flex-1"><h2 className="truncate text-base font-semibold text-foreground">{company.name}</h2><div className="mt-1 flex flex-wrap items-center gap-2"><StatusBadge status={company.status} /><span className="text-[8px] text-muted-foreground">Since {formatDate(company.createdAt)}</span></div></div><button type="button" onClick={onFollow} aria-pressed={followed} className={cn("flex h-8 items-center gap-1.5 rounded-lg border px-2.5 text-[9px]", followed ? "border-primary/30 bg-primary/10 text-primary" : "border-border text-muted-foreground")}><Star className={cn("h-3 w-3", followed && "fill-current")} />{followed ? "Following" : "Follow"}</button><button type="button" aria-label="Close" onClick={onClose} className="grid h-8 w-8 place-items-center rounded-lg text-muted-foreground hover:bg-foreground/[0.06] hover:text-foreground"><X className="h-4 w-4" /></button></div>
    <div className="relative mt-4 flex gap-2">{[[UserRound, "Contact"], [Mail, "Email"], [Phone, "Call"], [MessageSquareText, "Note"]].map(([Icon, label]) => <button key={label as string} type="button" onClick={() => label === "Note" ? setNoteOpen(true) : toast.success(`${label as string} action started for ${company.name}`)} className="grid w-12 place-items-center gap-1 rounded-lg border border-border bg-foreground/[0.02] py-2 text-[8px] text-muted-foreground hover:border-primary/25 hover:text-primary"><Icon className="h-3.5 w-3.5" />{label as string}</button>)}<button type="button" aria-label="More" aria-expanded={menuOpen} onClick={() => setMenuOpen((open) => !open)} className="grid w-12 place-items-center gap-1 rounded-lg border border-border bg-foreground/[0.02] py-2 text-[8px] text-muted-foreground hover:border-primary/25 hover:text-primary"><EllipsisVertical className="h-3.5 w-3.5" />More</button>{menuOpen ? <div className="absolute right-0 top-12 z-30 w-36 rounded-lg border border-border bg-popover/95 p-1 shadow-floating backdrop-blur-xl"><button type="button" onClick={onEdit} className="block w-full rounded-md px-2.5 py-2 text-left text-[9px] text-foreground hover:bg-foreground/[0.06]">Edit company</button><button type="button" onClick={onDelete} className="block w-full rounded-md px-2.5 py-2 text-left text-[9px] text-destructive hover:bg-destructive/10">Delete company</button></div> : null}</div></header>
    <nav className="mt-4 flex border-b border-border px-4">{tabs.map((item) => <button key={item.id} type="button" onClick={() => setTab(item.id)} className={cn("whitespace-nowrap border-b-2 px-2 py-3 text-[8px]", tab === item.id ? "border-primary text-foreground" : "border-transparent text-muted-foreground")}>{item.label}</button>)}</nav>
    <div className="min-h-0 flex-1 overflow-y-auto p-4">{tab === "overview" ? <div className="space-y-4"><div className="grid grid-cols-[1.05fr_.95fr] gap-3"><dl className="space-y-3 px-1 text-[9px]">{[["Industry", company.industry], ["Company Size", company.size], ["Revenue", company.revenue], ["Website", company.website], ["Phone", company.phone], ["Headquarters", company.headquarters]].map(([label, value]) => <div key={label} className="grid grid-cols-[76px_1fr] gap-2"><dt className="text-muted-foreground">{label}</dt><dd className={cn("break-words text-foreground", label === "Website" && "text-primary")}>{value}</dd></div>)}<div className="grid grid-cols-[76px_1fr] items-center gap-2"><dt className="text-muted-foreground">Owner</dt><dd className="flex items-center gap-2 text-foreground"><Avatar className="h-5 w-5"><AvatarFallback className="text-[7px]">{getInitials(company.owner)}</AvatarFallback></Avatar>{company.owner}</dd></div><div className="grid grid-cols-[76px_1fr] gap-2"><dt className="pt-1 text-muted-foreground">Tags</dt><dd className="flex flex-wrap gap-1">{company.tags.map((tag) => <span key={tag} className="rounded-full border border-emerald-400/20 bg-emerald-400/10 px-2 py-1 text-[7px] text-emerald-300">{tag}</span>)}</dd></div></dl>
      <div className="space-y-3"><section className="orion-glass-control rounded-xl p-3"><h3 className="text-[9px] font-medium text-foreground">Company Score</h3><div className="mx-auto mt-2 grid h-20 w-20 place-items-center rounded-full p-1" style={{ background: `conic-gradient(#25d9c2 ${company.score * 3.6}deg, rgba(52,82,80,.35) 0deg)` }}><div className="grid h-full w-full place-items-center rounded-full bg-[#071416]"><div className="text-center"><span className="block text-xl font-semibold text-foreground">{company.score}</span><span className="text-[7px] text-primary">Excellent</span></div></div></div><p className="mt-2 text-[8px] text-success">↑ 12 pts <span className="text-muted-foreground">vs last month</span></p></section>
      <section className="orion-glass-control rounded-xl p-3"><div className="flex items-center justify-between"><h3 className="text-[9px] font-medium text-foreground">Contacts at {company.name.split(" ")[0]} ({Math.max(contacts.length, 24)})</h3><button type="button" onClick={() => setTab("contacts")} className="text-[7px] text-primary">View all</button></div><div className="mt-2 space-y-2">{contacts.slice(0, 3).map((contact) => <button key={contact.id} type="button" onClick={() => onContact(contact.id)} className="flex w-full items-center gap-2 text-left"><Avatar className="h-6 w-6"><AvatarFallback className="text-[7px]">{getInitials(contact.name)}</AvatarFallback></Avatar><span><span className="block text-[8px] text-foreground">{contact.name}</span><span className="block text-[7px] text-muted-foreground">{contact.title}</span></span></button>)}</div>{contacts.length > 3 ? <button type="button" onClick={() => setTab("contacts")} className="mt-2 w-full rounded-full border border-border py-1 text-[7px] text-muted-foreground">+ {contacts.length - 3} more contacts</button> : null}</section></div></div>
      <div className="grid grid-cols-2 gap-3"><section className="orion-glass-control rounded-xl p-3"><div className="flex items-center justify-between"><h3 className="text-[10px] font-medium text-foreground">Notes</h3><button type="button" onClick={() => setNoteOpen((open) => !open)} className="text-[7px] text-primary">{noteOpen ? "Cancel" : "Add Note"}</button></div>{noteOpen ? <form onSubmit={submitNote} className="mt-2"><textarea autoFocus value={note} onChange={(event) => setNote(event.target.value)} placeholder="Add company context…" className="min-h-14 w-full resize-none rounded-lg border border-border bg-black/10 p-2 text-[8px] text-foreground outline-none" /><button type="submit" className="mt-1 rounded-md bg-primary/15 px-2 py-1 text-[7px] text-primary">Save note</button></form> : <div className="mt-2 space-y-2">{company.notes.slice(0, 2).map((item) => <p key={item} className="text-[8px] leading-4 text-foreground">{item}</p>)}<p className="pt-1 text-[7px] text-muted-foreground">{company.owner} · May 20, 2024</p></div>}</section><section className="orion-glass-control rounded-xl p-3"><div className="flex items-center justify-between"><h3 className="text-[10px] font-medium text-foreground">Activity</h3><button type="button" onClick={() => setTab("activity")} className="text-[7px] text-primary">View all</button></div><div className="mt-2 space-y-2">{activity.map(([item, date], index) => <div key={item} className="flex items-center gap-2"><span className={cn("grid h-5 w-5 place-items-center rounded text-white", index === 0 ? "bg-emerald-500/40" : index === 1 ? "bg-sky-500/40" : "bg-blue-500/40")}><FileText className="h-2.5 w-2.5" /></span><span className="min-w-0 flex-1 truncate text-[7px] text-foreground">{item}</span><span className="text-[6px] text-muted-foreground">{date}</span></div>)}</div></section></div></div> : null}
    {tab === "contacts" ? <div className="space-y-2">{contacts.map((contact) => <button key={contact.id} type="button" onClick={() => onContact(contact.id)} className="orion-glass-control flex w-full items-center gap-3 rounded-xl p-3 text-left"><Avatar className="h-8 w-8"><AvatarFallback className="text-[8px]">{getInitials(contact.name)}</AvatarFallback></Avatar><span className="flex-1"><span className="block text-[10px] text-foreground">{contact.name}</span><span className="text-[8px] text-muted-foreground">{contact.title} · {contact.email}</span></span><ChevronRight className="h-3.5 w-3.5 text-muted-foreground" /></button>)}</div> : null}
    {tab === "deals" ? <div className="space-y-2">{Array.from({ length: company.deals }, (_, index) => <article key={index} className="orion-glass-control flex items-center justify-between rounded-xl p-3"><div><p className="text-[10px] text-foreground">{index ? `${company.name} Expansion ${index + 1}` : `${company.name} Enterprise Plan`}</p><p className="mt-1 text-[8px] text-muted-foreground">Proposal · closes Sep {12 + index}, 2026</p></div><span className="text-[10px] font-medium text-primary">{money(Math.max(2500, Math.round(company.dealValue / company.deals)))}</span></article>)}</div> : null}
    {tab === "activity" ? <div className="space-y-4">{activity.concat([["Company record created", formatDate(company.createdAt)]]).map(([item, date]) => <div key={item} className="flex gap-3"><span className="grid h-7 w-7 place-items-center rounded-full bg-primary/10 text-primary"><Activity className="h-3.5 w-3.5" /></span><div><p className="text-[10px] text-foreground">{item}</p><p className="mt-1 text-[8px] text-muted-foreground">{date} · {company.owner}</p></div></div>)}</div> : null}
    {tab === "files" ? <div className="space-y-2">{["contract.pdf", "security_review.pdf", "implementation_plan.docx"].map((file, index) => <article key={file} className="orion-glass-control flex items-center gap-3 rounded-xl p-3"><span className="grid h-8 w-8 place-items-center rounded-lg bg-emerald-500/15 text-emerald-400"><FileText className="h-4 w-4" /></span><span className="flex-1"><span className="block text-[10px] text-foreground">{file}</span><span className="text-[8px] text-muted-foreground">{index ? "DOC · 860 KB" : "PDF · 2.4 MB"}</span></span><button type="button" aria-label={`Download ${file}`} onClick={() => toast.success(`${file} download started`)} className="text-muted-foreground hover:text-primary"><Download className="h-3.5 w-3.5" /></button></article>)}</div> : null}</div>
  </aside></div>;
}

function DetailsPanel({ selection, contacts, companies, followed, onFollow, onClose, onEdit, onDelete, onSelect, onAddNote, onStatusChange }: { selection: NonNullable<Selection>; contacts: ContactRecord[]; companies: CompanyRecord[]; followed: Set<string>; onFollow: () => void; onClose: () => void; onEdit: () => void; onDelete: () => void; onSelect: (selection: Selection) => void; onAddNote: (note: string) => void; onStatusChange: (status: ContactStatus) => void }) {
  const [tab, setTab] = useState<"overview" | "activity" | "notes">("overview");
  const [note, setNote] = useState("");
  const isContact = selection.kind === "contacts";
  const contact = isContact ? contacts.find((item) => item.id === selection.id) : undefined;
  const company = isContact ? companies.find((item) => item.id === contact?.companyId) : companies.find((item) => item.id === selection.id);
  if (!company && !contact) return null;
  const title = contact?.name ?? company!.name;
  const subtitle = contact?.title ?? company!.industry;
  const notes = contact?.notes ?? company!.notes;
  const companyContacts = company ? contacts.filter((item) => item.companyId === company.id) : [];
  const recordId = contact?.id ?? company!.id;

  const contactProfile = contact ? <ContactProfilePanel contact={contact} company={company} onClose={onClose} onEdit={onEdit} onDelete={onDelete} onCompany={() => company && onSelect({ kind: "companies", id: company.id })} onAddNote={onAddNote} onStatusChange={onStatusChange} /> : null;
  if (contactProfile) return contactProfile;
  const companyProfile = company ? <CompanyProfilePanel company={company} contacts={companyContacts} followed={followed.has(recordId)} onFollow={onFollow} onClose={onClose} onEdit={onEdit} onDelete={onDelete} onContact={(id) => onSelect({ kind: "contacts", id })} onAddNote={onAddNote} /> : null;
  if (companyProfile) return companyProfile;

  return <div className="fixed inset-0 z-40 bg-black/45 backdrop-blur-[2px]" role="presentation" onMouseDown={(event) => { if (event.target === event.currentTarget) onClose(); }}><aside aria-label={`${title} details`} className="neon-panel absolute bottom-3 right-3 top-3 flex w-[460px] max-w-[calc(100vw-24px)] flex-col overflow-hidden rounded-2xl shadow-floating"><header className="p-5 pb-3"><div className="flex items-start gap-3"><Avatar className="h-11 w-11 border border-primary/20"><AvatarFallback className="bg-primary/10 text-primary">{getInitials(title)}</AvatarFallback></Avatar><div className="min-w-0 flex-1"><h2 className="truncate text-base font-semibold text-foreground">{title}</h2><p className="text-xs text-muted-foreground">{subtitle}</p><div className="mt-2 flex items-center gap-2"><StatusBadge status={contact?.status ?? company!.status} /><span className="text-[9px] text-muted-foreground">Since {formatDate(contact?.createdAt ?? company!.createdAt)}</span></div></div><button type="button" onClick={onFollow} aria-pressed={followed.has(recordId)} className={cn("flex h-8 items-center gap-1.5 rounded-lg border px-2.5 text-[10px]", followed.has(recordId) ? "border-primary/30 bg-primary/10 text-primary" : "border-border text-muted-foreground")}><Star className={cn("h-3 w-3", followed.has(recordId) && "fill-current")} />{followed.has(recordId) ? "Following" : "Follow"}</button><button type="button" aria-label="Close" onClick={onClose} className="grid h-8 w-8 place-items-center text-muted-foreground"><X className="h-4 w-4" /></button></div>
    <div className="mt-4 grid grid-cols-5 gap-2">{[[Mail, "Email"], [Phone, "Call"], [MessageSquareText, "Note"], [FileText, "Task"], [EllipsisVertical, "More"]].map(([Icon, label]) => <button key={label as string} type="button" onClick={() => label === "Note" ? setTab("notes") : toast.success(`${label as string} action started for ${title}`)} className="orion-glass-control grid place-items-center gap-1 rounded-lg py-2 text-[9px] text-muted-foreground hover:text-primary"><Icon className="h-3.5 w-3.5" />{label as string}</button>)}</div></header>
    <nav className="flex border-b border-border px-5">{(["overview", "activity", "notes"] as const).map((item) => <button key={item} type="button" onClick={() => setTab(item)} className={cn("border-b-2 px-3 py-3 text-[10px] capitalize", tab === item ? "border-primary text-primary" : "border-transparent text-muted-foreground")}>{item}</button>)}</nav>
    <div className="min-h-0 flex-1 overflow-y-auto p-5">{tab === "overview" ? <div className="space-y-4"><section><h3 className="text-[10px] font-semibold uppercase tracking-wider text-muted-foreground">Overview</h3><dl className="mt-3 grid grid-cols-2 gap-3 text-xs">{(contact ? [["Email", contact.email], ["Phone", contact.phone], ["Company", company?.name ?? "—"], ["Owner", contact.owner]] : [["Industry", company!.industry], ["Company size", company!.size], ["Revenue", company!.revenue], ["Headquarters", company!.headquarters], ["Website", company!.website], ["Owner", company!.owner]]).map(([label, value]) => <div key={label} className="orion-glass-control rounded-xl p-3"><dt className="text-[9px] text-muted-foreground">{label}</dt><dd className="mt-1 break-words font-medium text-foreground">{value}</dd></div>)}</dl></section>{contact && company ? <button type="button" onClick={() => onSelect({ kind: "companies", id: company.id })} className="orion-glass-control flex w-full items-center gap-3 rounded-xl p-3 text-left"><Building2 className="h-5 w-5 text-primary" /><span className="flex-1"><span className="block text-xs font-medium text-foreground">{company.name}</span><span className="text-[9px] text-muted-foreground">Open company relationship</span></span><ChevronRight className="h-4 w-4 text-muted-foreground" /></button> : null}{!contact && company ? <section><div className="flex items-center justify-between"><h3 className="text-[10px] font-semibold uppercase tracking-wider text-muted-foreground">Contacts at {company.name}</h3><span className="text-[9px] text-primary">{companyContacts.length} people</span></div><div className="mt-2 space-y-2">{companyContacts.map((item) => <button key={item.id} type="button" onClick={() => onSelect({ kind: "contacts", id: item.id })} className="orion-glass-control flex w-full items-center gap-3 rounded-xl p-2.5 text-left"><Avatar className="h-8 w-8"><AvatarFallback className="text-[9px]">{getInitials(item.name)}</AvatarFallback></Avatar><span className="flex-1"><span className="block text-xs text-foreground">{item.name}</span><span className="text-[9px] text-muted-foreground">{item.title}</span></span><ChevronRight className="h-3.5 w-3.5 text-muted-foreground" /></button>)}</div></section> : null}</div> : null}
    {tab === "activity" ? <div className="space-y-3">{["Relationship record reviewed", "Follow-up email sent", "Meeting notes updated", "Owner assignment confirmed"].map((item, index) => <div key={item} className="flex gap-3"><span className="mt-1 grid h-7 w-7 place-items-center rounded-full bg-primary/10 text-primary"><Activity className="h-3.5 w-3.5" /></span><div><p className="text-xs text-foreground">{item}</p><p className="mt-1 text-[9px] text-muted-foreground">{index + 1} day{index ? "s" : ""} ago · {contact?.owner ?? company!.owner}</p></div></div>)}</div> : null}
    {tab === "notes" ? <div><form onSubmit={(event) => { event.preventDefault(); if (!note.trim()) return; onAddNote(note.trim()); setNote(""); }} className="orion-glass-control rounded-xl p-3"><label className="text-[10px] text-muted-foreground">Add a private team note<textarea value={note} onChange={(e) => setNote(e.target.value)} className="mt-2 min-h-20 w-full resize-none bg-transparent text-xs text-foreground outline-none" placeholder="Capture context, next steps, or risks…" /></label><div className="text-right"><button type="submit" className="rounded-lg bg-primary/15 px-3 py-1.5 text-[10px] font-medium text-primary">Add note</button></div></form><div className="mt-3 space-y-2">{notes.map((item, index) => <article key={`${item}-${index}`} className="orion-glass-control rounded-xl p-3"><p className="text-xs text-foreground">{item}</p><p className="mt-2 text-[9px] text-muted-foreground">Alex Morgan · {index + 1}d ago</p></article>)}</div></div> : null}</div>
    <footer className="grid grid-cols-2 gap-2 border-t border-border p-4"><button type="button" onClick={onEdit} className="rounded-lg border border-border py-2 text-xs text-foreground">Edit record</button><button type="button" onClick={onDelete} className="rounded-lg border border-destructive/25 bg-destructive/10 py-2 text-xs text-destructive">Delete record</button></footer></aside></div>;
}

export function RelationshipsWorkspace({ initialView = "contacts" }: { initialView?: RelationshipView }) {
  const searchParams = useSearchParams();
  const [view, setView] = useState<RelationshipView>(initialView);
  const [contacts, setContacts] = useState(mockContacts);
  const [companies, setCompanies] = useState(mockCompanies);
  const [selection, setSelection] = useState<Selection>(() => searchParams.get("contact") ? { kind: "contacts", id: searchParams.get("contact")! } : searchParams.get("company") ? { kind: "companies", id: searchParams.get("company")! } : null);
  const [dialog, setDialog] = useState<{ kind: RelationshipView; id?: string } | null>(null);
  const [query, setQuery] = useState("");
  const [owner, setOwner] = useState("all");
  const [companyFilter, setCompanyFilter] = useState("all");
  const [status, setStatus] = useState<ContactStatus | "all">("all");
  const [page, setPage] = useState(1);
  const [followed, setFollowed] = useState<Set<string>>(() => new Set());
  const importRef = useRef<HTMLInputElement>(null);
  const companyMap = useMemo(() => new Map(companies.map((item) => [item.id, item])), [companies]);
  const filtered = useMemo(() => {
    const normalized = query.trim().toLowerCase();
    if (view === "contacts") return contacts.filter((item) => owner === "all" || item.owner === owner).filter((item) => companyFilter === "all" || item.companyId === companyFilter).filter((item) => status === "all" || item.status === status).filter((item) => !normalized || `${item.name} ${item.title} ${item.email} ${companyMap.get(item.companyId)?.name}`.toLowerCase().includes(normalized));
    return companies.filter((item) => owner === "all" || item.owner === owner).filter((item) => status === "all" || item.status === status).filter((item) => !normalized || `${item.name} ${item.industry} ${item.headquarters}`.toLowerCase().includes(normalized));
  }, [companyFilter, companyMap, companies, contacts, owner, query, status, view]);
  const pageSize = 8;
  const pageCount = Math.max(1, Math.ceil(filtered.length / pageSize));
  const pageItems = filtered.slice((Math.min(page, pageCount) - 1) * pageSize, Math.min(page, pageCount) * pageSize);
  const selectedContact = dialog?.kind === "contacts" ? contacts.find((item) => item.id === dialog.id) : undefined;
  const selectedCompany = dialog?.kind === "companies" ? companies.find((item) => item.id === dialog.id) : undefined;

  function changeView(next: RelationshipView) { setView(next); setQuery(""); setOwner("all"); setCompanyFilter("all"); setStatus("all"); setPage(1); }
  function saveRecord(draft: ContactDraft | CompanyDraft) {
    if (dialog?.kind === "contacts") {
      const value = draft as ContactDraft;
      setContacts((current) => dialog.id ? current.map((item) => item.id === dialog.id ? { ...item, ...value } : item) : [{ ...value, id: `ct-${Date.now()}`, tags: ["New"], lastContacted: "Just now", createdAt: new Date().toISOString().slice(0, 10), notes: [] }, ...current]);
      toast.success(dialog.id ? "Contact updated" : "Contact added");
    } else {
      const value = draft as CompanyDraft;
      setCompanies((current) => dialog?.id ? current.map((item) => item.id === dialog.id ? { ...item, ...value } : item) : [{ ...value, id: `co-${Date.now()}`, revenue: "Not set", score: 50, deals: 0, dealValue: 0, tags: ["New"], createdAt: new Date().toISOString().slice(0, 10), notes: [] }, ...current]);
      toast.success(dialog?.id ? "Company updated" : "Company added");
    }
    setDialog(null); setPage(1);
  }
  function deleteSelection() {
    if (!selection) return;
    if (selection.kind === "contacts") setContacts((current) => current.filter((item) => item.id !== selection.id));
    else { setCompanies((current) => current.filter((item) => item.id !== selection.id)); setContacts((current) => current.map((item) => item.companyId === selection.id ? { ...item, companyId: "" } : item)); }
    toast.success(`${selection.kind === "contacts" ? "Contact" : "Company"} deleted`); setSelection(null);
  }
  function addNote(note: string) {
    if (!selection) return;
    if (selection.kind === "contacts") setContacts((current) => current.map((item) => item.id === selection.id ? { ...item, notes: [note, ...item.notes] } : item));
    else setCompanies((current) => current.map((item) => item.id === selection.id ? { ...item, notes: [note, ...item.notes] } : item));
    toast.success("Note added");
  }

  return <div className="space-y-3"><header className="flex flex-wrap items-start justify-between gap-3"><div><h1 className="text-xl font-semibold tracking-tight text-foreground">Contacts &amp; Companies</h1><p className="mt-0.5 text-[11px] text-muted-foreground">Manage your relationships and build stronger connections.</p></div><div className="flex flex-wrap gap-2"><input ref={importRef} type="file" accept=".csv" className="hidden" onChange={(e) => { if (e.target.files?.[0]) toast.success(`${e.target.files[0].name} queued for validation`); e.target.value = ""; }} /><button type="button" onClick={() => importRef.current?.click()} className="orion-glass-control flex h-8 items-center gap-2 rounded-lg px-3 text-[10px]"><Download className="h-3.5 w-3.5" />Import</button><button type="button" onClick={() => setDialog({ kind: "contacts" })} className="orion-glass-control flex h-8 items-center gap-2 rounded-lg px-3 text-[10px]"><UserRound className="h-3.5 w-3.5" />Add Contact</button><button type="button" onClick={() => setDialog({ kind: "companies" })} className="orion-add-widget flex h-8 items-center gap-2 rounded-lg px-3 text-[10px] font-semibold"><Building2 className="h-3.5 w-3.5" />Add Company</button></div></header>
  <nav className="flex border-b border-border"><button type="button" onClick={() => changeView("contacts")} className={cn("border-b-2 px-1 py-2.5 text-[10px]", view === "contacts" ? "border-primary text-primary" : "border-transparent text-muted-foreground")}>All Contacts</button><button type="button" onClick={() => changeView("companies")} className={cn("ml-7 border-b-2 px-1 py-2.5 text-[10px]", view === "companies" ? "border-primary text-primary" : "border-transparent text-muted-foreground")}>All Companies</button></nav>
  <section className="grid grid-cols-2 gap-3 lg:grid-cols-4"><MetricCard label="Total Contacts" value="2,847" delta="8.6%" icon={UsersRound} /><MetricCard label="My Contacts" value="1,250" delta="5.4%" icon={UserRound} /><MetricCard label="Total Companies" value="1,065" delta="6.8%" icon={Building2} /><MetricCard label="New This Month" value="186" delta="12.8%" icon={TrendingUp} gold /></section>
  <section className="orion-panel overflow-visible"><div className="flex flex-wrap items-center gap-2 border-b border-border p-3"><label className="orion-glass-control flex h-8 min-w-52 flex-1 items-center gap-2 rounded-lg px-3"><Search className="h-3.5 w-3.5 text-muted-foreground" /><input aria-label={`Search ${view}`} value={query} onChange={(e) => { setQuery(e.target.value); setPage(1); }} placeholder={`Search ${view}...`} className="min-w-0 flex-1 bg-transparent text-[10px] text-foreground outline-none" /></label><select aria-label="Owner filter" value={owner} onChange={(e) => { setOwner(e.target.value); setPage(1); }} className="orion-glass-control h-8 rounded-lg px-2 text-[10px]"><option value="all">All owners</option>{owners.map((item) => <option key={item}>{item}</option>)}</select>{view === "contacts" ? <select aria-label="Company filter" value={companyFilter} onChange={(e) => { setCompanyFilter(e.target.value); setPage(1); }} className="orion-glass-control h-8 rounded-lg px-2 text-[10px]"><option value="all">All companies</option>{companies.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select> : null}<select aria-label="Relationship filter" value={status} onChange={(e) => { setStatus(e.target.value as ContactStatus | "all"); setPage(1); }} className="orion-glass-control h-8 rounded-lg px-2 text-[10px]"><option value="all">All relationships</option>{statuses.map((item) => <option key={item} value={item}>{item}</option>)}</select><button type="button" aria-label="Table settings" onClick={() => toast.info("Table preferences are ready to customize")} className="orion-glass-control grid h-8 w-8 place-items-center rounded-lg"><Settings2 className="h-3.5 w-3.5" /></button></div>
  <div className="overflow-x-auto"><table className="w-full min-w-[900px] text-left"><thead><tr className="border-b border-border bg-foreground/[0.02] text-[9px] text-muted-foreground">{view === "contacts" ? <><th className="px-4 py-3">Contact</th><th>Company</th><th>Email</th><th>Phone</th><th>Owner</th><th>Relationship</th><th>Last Contacted</th></> : <><th className="px-4 py-3">Company</th><th>Industry</th><th>Contacts</th><th>Open Deals</th><th>Pipeline</th><th>Owner</th><th>Relationship</th></>}<th className="w-12 px-4 text-right">Actions</th></tr></thead><tbody>{view === "contacts" ? (pageItems as ContactRecord[]).map((item) => { const company = companyMap.get(item.companyId); return <tr key={item.id} className="border-b border-border/60 text-[10px] hover:bg-foreground/[0.025]"><td className="px-4 py-2.5"><button type="button" onClick={() => setSelection({ kind: "contacts", id: item.id })} className="flex items-center gap-2 text-left"><Avatar className="h-8 w-8"><AvatarFallback className="text-[9px]">{getInitials(item.name)}</AvatarFallback></Avatar><span><span className="block font-medium text-foreground">{item.name}</span><span className="text-[9px] text-muted-foreground">{item.title}</span></span></button></td><td><button type="button" onClick={() => company && setSelection({ kind: "companies", id: company.id })} className="flex items-center gap-2 text-foreground hover:text-primary"><Building2 className="h-3.5 w-3.5 text-primary" />{company?.name ?? "Unassigned"}</button></td><td className="text-muted-foreground">{item.email}</td><td className="text-muted-foreground">{item.phone}</td><td><Avatar className="h-6 w-6" title={item.owner}><AvatarFallback className="text-[8px]">{getInitials(item.owner)}</AvatarFallback></Avatar></td><td><StatusBadge status={item.status} /></td><td className="text-muted-foreground">{item.lastContacted}</td><td className="px-4 text-right"><button type="button" aria-label={`Actions for ${item.name}`} onClick={() => setSelection({ kind: "contacts", id: item.id })} className="text-muted-foreground"><EllipsisVertical className="h-4 w-4" /></button></td></tr> }) : (pageItems as CompanyRecord[]).map((item) => <tr key={item.id} className="border-b border-border/60 text-[10px] hover:bg-foreground/[0.025]"><td className="px-4 py-3"><button type="button" onClick={() => setSelection({ kind: "companies", id: item.id })} className="flex items-center gap-2 font-medium text-foreground hover:text-primary"><span className="grid h-7 w-7 place-items-center rounded-md border border-primary/15 bg-primary/10 text-primary">{item.name[0]}</span>{item.name}</button></td><td className="text-muted-foreground">{item.industry}</td><td>{contacts.filter((contact) => contact.companyId === item.id).length}</td><td>{item.deals}</td><td className="font-medium text-foreground">{money(item.dealValue)}</td><td><Avatar className="h-6 w-6" title={item.owner}><AvatarFallback className="text-[8px]">{getInitials(item.owner)}</AvatarFallback></Avatar></td><td><StatusBadge status={item.status} /></td><td className="px-4 text-right"><button type="button" aria-label={`Actions for ${item.name}`} onClick={() => setSelection({ kind: "companies", id: item.id })} className="text-muted-foreground"><EllipsisVertical className="h-4 w-4" /></button></td></tr>)}</tbody></table>{pageItems.length === 0 ? <div className="grid min-h-48 place-items-center text-center"><div><Search className="mx-auto h-7 w-7 text-muted-foreground" /><p className="mt-2 text-sm text-foreground">No {view} found</p><p className="text-xs text-muted-foreground">Try adjusting your search or filters.</p></div></div> : null}</div>
  <footer className="flex flex-wrap items-center justify-between gap-3 px-4 py-3 text-[10px] text-muted-foreground"><p>Showing {filtered.length ? (Math.min(page, pageCount) - 1) * pageSize + 1 : 0} to {Math.min(Math.min(page, pageCount) * pageSize, filtered.length)} of {filtered.length} {view}</p><div className="flex items-center gap-1"><button type="button" aria-label="Previous page" disabled={page <= 1} onClick={() => setPage((value) => Math.max(1, value - 1))} className="grid h-7 w-7 place-items-center rounded-lg border border-border disabled:opacity-40"><ChevronLeft className="h-3.5 w-3.5" /></button>{Array.from({ length: pageCount }, (_, index) => index + 1).map((value) => <button key={value} type="button" onClick={() => setPage(value)} aria-current={value === Math.min(page, pageCount) ? "page" : undefined} className={cn("h-7 min-w-7 rounded-lg", value === Math.min(page, pageCount) ? "border border-primary/30 bg-primary/10 text-primary" : "text-muted-foreground")}>{value}</button>)}<button type="button" aria-label="Next page" disabled={page >= pageCount} onClick={() => setPage((value) => Math.min(pageCount, value + 1))} className="grid h-7 w-7 place-items-center rounded-lg border border-border disabled:opacity-40"><ChevronRight className="h-3.5 w-3.5" /></button></div></footer></section>
  {selection ? <DetailsPanel selection={selection} contacts={contacts} companies={companies} followed={followed} onFollow={() => setFollowed((current) => { const next = new Set(current); if (next.has(selection.id)) next.delete(selection.id); else next.add(selection.id); return next; })} onClose={() => setSelection(null)} onEdit={() => setDialog(selection)} onDelete={deleteSelection} onSelect={setSelection} onAddNote={addNote} onStatusChange={(nextStatus) => { if (selection.kind !== "contacts") return; setContacts((current) => current.map((item) => item.id === selection.id ? { ...item, status: nextStatus } : item)); toast.success("Contact status updated"); }} /> : null}
  {dialog ? <RecordDialog kind={dialog.kind} companies={companies} contact={selectedContact} company={selectedCompany} onClose={() => setDialog(null)} onSave={saveRecord} /> : null}</div>;
}
